import {useEffect,useRef,useState} from 'react';
import {Link,Outlet,useNavigate,useParams,useRouterState,useSearch} from '@tanstack/react-router';
import {useMutation,useQueries,useQuery,useQueryClient} from '@tanstack/react-query';
import {ArrowLeft,Heart,Home as HomeIcon,Search,ShoppingCart,SlidersHorizontal,Trash2,UserRound,Wallet as WalletIcon,LogOut,Eye,EyeOff,CheckCircle2,ImageIcon} from 'lucide-react';
import {api} from './api';
import type {Cart,CatalogFilters,Nft,Wallet} from './contracts';
import {formatEth,mulEth} from './lib/money';
import {Button} from './components/ui/button';
import {LiveState,errorMessage,useSession} from './state';
import {clearIdentity} from './live';

// TanStack Router requires complete validated search params for links to catalogue routes.
const defaultCatalogSearch = {q:'',category:'all',sort:'popular',page:1,maxPrice:'',network:'all'} as const;
const categories=[['Arte digital',33],['Fotografia',12],['Música',65],['Arte 3D',39],['Colecionáveis',23],['Generativa',17],['Jogos',19],['Assinaturas',13],['Utilidade',18]] as const;
const networks=[['Ethereum',119],['Polygon',78],['Solana',86]] as const;
function Loading({count=3}:{count?:number}){return <div className="grid-nfts" aria-label="Carregando conteúdo" role="status">{Array.from({length:count},(_,i)=><div className="skeleton" key={i} aria-hidden="true"/>)}</div>}
function Feedback({message}:{message:string}){return <p role="alert" className="error">{message}</p>}
function useCart(){const {data:user}=useSession();return useQuery({queryKey:['cart',user?.id??'guest'],queryFn:api.cart});}
function useCartNfts(cart:Cart|undefined){return useQueries({queries:(cart?.items??[]).map(item=>({queryKey:['nft',item.nftId],queryFn:()=>api.nft(item.nftId),retry:false,staleTime:20000}))});}
function Required({children}:{children:React.ReactNode}){const {data:user,isPending}=useSession();if(isPending)return <Loading count={1}/>;if(!user)return <section className="panel" style={{margin:'70px auto',maxWidth:500,textAlign:'center'}}><h1 className="section-title">Entre para continuar</h1><p className="note" style={{margin:'16px 0'}}>Para acessar essa área, faça login. Seu carrinho será preservado.</p><Link className="btn" to="/login" onClick={()=>sessionStorage.setItem('kurio-return',window.location.pathname+window.location.search)}>Entrar</Link></section>;return <>{children}</>}

function Footer(){return <footer className="site-footer"><div className="shell footer-feature"><div><div className="footer-disc">W</div><h3>Segurança da carteira</h3><p>Proteja sua carteira e colecione arte digital verificada com confiança.</p></div><div><div className="footer-disc">C</div><h3>Criadores em destaque</h3><p>Conheça artistas, estúdios e comunidades que moldam a cultura digital na rede.</p></div><div><div className="footer-disc">D</div><h3>Alertas de lançamentos</h3><p>Receba calendários de cunhagem, novidades de listas de acesso e análises de mercado.</p></div><div><h3>Antecipe-se ao próximo lançamento</h3><div className="newsletter-input"><input aria-label="E-mail para newsletter" placeholder="digite seu e-mail..." disabled/><button disabled title="Fora do escopo do challenge">Enviar</button></div><p>Receba lançamentos selecionados, histórias de criadores e novidades do mercado.</p></div></div><div className="footer-band"><div className="shell"><b>KURIO</b><span>Feito para colecionadores,<br/>criadores e cultura</span><span>contato@email.com</span><span>+55 11 4002 8922</span></div></div><div className="shell footer-grid"><div><h3>Meu perfil</h3><p><Link to="/profile">Meu perfil</Link></p><p>Minha coleção</p><p>Atividade</p><p>Estúdio do criador</p><p>Lista de interesse</p></div><div><h3>Central de ajuda</h3><p>Central de ajuda</p><p>Como comprar NFTs</p><p>Carteira e segurança</p><p>Política do mercado</p></div><div><h3>Coleções</h3>{categories.slice(0,5).map(([c])=><p key={c}>{c}</p>)}</div><div><h3>Redes sociais</h3><p>Instagram · X · YouTube</p><h3 style={{marginTop:20}}>Carteiras compatíveis</h3><p>METAMASK · WALLETCONNECT · COINBASE</p></div></div><p className="copyright">© 2026 Kurio. Propriedade digital para todos.</p></footer>}
function Header(){const {data:user}=useSession();const cart=useCart();const navigate=useNavigate();const pathname=useRouterState({select:s=>s.location.pathname});const [showSearch,setShowSearch]=useState(false);const [term,setTerm]=useState('');const count=cart.data?.items.reduce((s,i)=>s+i.quantity,0)??0;return <><header className="site-header"><div className="site-header-inner shell"><Link className="brand" to="/" search={defaultCatalogSearch}>KURIO</Link><nav className="top-nav" aria-label="Menu principal"><Link to="/" className={pathname==='/'?'active':''} search={defaultCatalogSearch}>Início</Link><Link to="/market" className={pathname.includes('market')||pathname.includes('nfts')?'active':''} search={defaultCatalogSearch}>Mercado</Link><span aria-disabled="true">Criadores</span><span aria-disabled="true">Aprenda</span></nav><div className="header-actions"><button aria-label="Pesquisar NFTs" className="icon-btn" onClick={()=>setShowSearch(v=>!v)}><Search size={21}/></button><Link aria-label={`Carrinho com ${count} NFTs`} className="icon-link" to="/cart"><ShoppingCart size={21}/>{count>0&&<span className="cart-bubble">{count}</span>}</Link>{user?<Link to="/profile" className="btn small"><UserRound size={15}/> Perfil</Link>:<Link to="/login" className="btn small"><LogOut size={15}/> Entrar</Link>}</div></div></header>{showSearch&&<form className="shell search-inline" onSubmit={e=>{e.preventDefault();void navigate({to:'/',search:{...defaultCatalogSearch,q:term}});setShowSearch(false)}}><Search size={18}/><input autoFocus type="search" value={term} onChange={e=>setTerm(e.target.value)} placeholder="Explore os NFTs..." aria-label="Pesquisar no catálogo"/><Button type="submit" className="small">Buscar</Button></form>}</>}
function MobileBar(){const pathname=useRouterState({select:s=>s.location.pathname});const cart=useCart();const count=cart.data?.items.reduce((s,i)=>s+i.quantity,0)??0;return <nav className="mobile-bar" aria-label="Navegação mobile"><Link aria-label="Início" className={pathname==='/'?'active':''} to="/" search={defaultCatalogSearch}><HomeIcon size={23} fill={pathname==='/'?'currentColor':'none'}/></Link><Link aria-label="Mercado e favoritos" to="/market" search={defaultCatalogSearch}><Heart size={23}/></Link><Link aria-label={`Carrinho com ${count} NFTs`} className={pathname==='/cart'?'active':''} to="/cart"><ShoppingCart size={23}/>{count>0&&<span className="cart-bubble">{count}</span>}</Link><Link aria-label="Perfil" className={pathname.includes('profile')?'active':''} to="/profile"><UserRound size={23}/></Link></nav>}
export function Layout(){return <><LiveState/><Header/><main className="shell page"><Outlet/></main><Footer/><MobileBar/></>}

function Favorite({id,className=''}:{id:string;className?:string}){const {data:user}=useSession();const qc=useQueryClient();const navigate=useNavigate();const key=['favorites',user?.id];const {data:favs=[]}=useQuery({queryKey:key,queryFn:api.favorites,enabled:!!user});const liked=favs.includes(id);const m=useMutation({mutationFn:()=>api.favorite(id,!liked),onMutate:async()=>{await qc.cancelQueries({queryKey:key});const before=qc.getQueryData<string[]>(key);qc.setQueryData<string[]>(key,(v=[])=>liked?v.filter(x=>x!==id):[...v,id]);return {before}},onError:(_e,_v,ctx)=>{qc.setQueryData(key,ctx?.before)},onSettled:()=>qc.invalidateQueries({queryKey:key})});return <button className={`card-fav ${className}`} aria-label={liked?'Remover dos favoritos':'Adicionar aos favoritos'} aria-pressed={liked} disabled={m.isPending} onClick={e=>{e.preventDefault();e.stopPropagation();if(user){m.mutate()}else{sessionStorage.setItem('kurio-return',window.location.pathname+window.location.search);void navigate({to:'/login'})}}}><Heart size={18} fill={liked?'currentColor':'none'}/></button>}
function NftCard({nft}:{nft:Nft}){return <article className="nft-card"><div className="art-wrap"><Link to="/nfts/$nftId" params={{nftId:nft.id}} aria-label={`Ver ${nft.title}`}><img className="art" src={nft.image} alt={`Retrato do NFT ${nft.title}`} loading="lazy" width="300" height="300"/></Link>{nft.edition==='Rare'&&<span className="tag-rare">RARO</span>}<Favorite id={nft.id}/></div><Link to="/nfts/$nftId" params={{nftId:nft.id}}><h3>{nft.title}</h3></Link><p className="price">{formatEth(nft.priceEth)}</p></article>}
function Catalog({mode='home'}:{mode?:'home'|'market'}){const route=mode==='home'?'/':'/market';const search=useSearch({strict:false}) as CatalogFilters;const navigate=useNavigate();const filters:Required<CatalogFilters>={q:search.q||'',category:search.category||'all',sort:search.sort||'popular',page:search.page||1,maxPrice:search.maxPrice||'',network:search.network||'all'};const [localPrice,setLocalPrice]=useState(12.3);const [mobileFilters,setMobileFilters]=useState(false);const [showSearch,setShowSearch]=useState(false);const {data,isPending,isFetching,isError,refetch}=useQuery({queryKey:['catalog',filters],queryFn:({signal})=>api.catalog(filters,signal),placeholderData:prev=>prev});const update=(next:Partial<CatalogFilters>)=>void navigate({to:route,search:{...filters,...next,page:next.page??1}});const category=(name:string)=>update({category:name});return <>
<div className="mobile-search"><div className="search-inline"><Search size={17} color="#b99a75"/><input type="search" aria-label="Explorar coleções" placeholder="Explorar coleções" value={filters.q} onChange={e=>update({q:e.target.value})}/></div><button aria-label="Abrir filtros" aria-expanded={mobileFilters} className="icon-btn" onClick={()=>setMobileFilters(v=>!v)}><SlidersHorizontal size={20}/></button></div>
{mode==='home'&&<section className="hero" aria-label="Destaque Kurio"><div className="hero-text"><span className="kicker">Bem-vindo à Kurio</span><h1>SEJA DONO DO FUTURO<br/>DA ARTE DIGITAL</h1><p>Descubra NFTs selecionados de criadores emergentes e consagrados. Colecione arte digital rara, apoie artistas e tenha uma parte da cultura da internet.</p><a className="btn" href="#catalogo">EXPLORAR</a></div><div><img className="hero-figure" src="/assets/emerald.webp" alt="NFT Emerald Ape com óculos verdes"/><div className="hero-dots">●●●</div></div></section>}
<section className="catalog-shell" id="catalogo"><aside className="filter-column"><div className="filter-block"><h2>Coleções</h2>{categories.map(([label,count])=><button key={label} className={`filter-option ${filters.category===label?'selected':''}`} onClick={()=>category(filters.category===label?'all':label)}><span>{label}</span><span>({count})</span></button>)}<h3>Faixa de preço</h3><input className="filter-range" aria-label="Preço máximo" type="range" min="0.02" max="12.30" step="0.01" value={localPrice} onChange={e=>setLocalPrice(+e.target.value)}/><p className="small-copy muted">Preço: 0,02 – {localPrice.toFixed(2).replace('.',',')} ETH</p><button className="btn small" type="button" onClick={()=>update({maxPrice:localPrice>=12.3?'':localPrice.toFixed(2)})}>Aplicar</button><h3>Rede</h3>{networks.map(([network,count])=><button key={network} className={`filter-option ${filters.network===network?'selected':''}`} onClick={()=>update({network:filters.network===network?'all':network})}><span>{network}</span><span>({count})</span></button>)}</div><div className="feature-tile"><strong>NFT EM DESTAQUE</strong><p style={{fontWeight:700,fontSize:13}}>OFERTA LIMITADA</p><img src="/assets/sage.webp" alt="Sage Nomad, NFT em destaque"/></div></aside>
<div className="catalog-main">{mode==='market'&&<div className="crumb">Início / Mercado</div>}
<div className="catalog-bar"><div className="catalog-tabs"><button className={`catalog-tab ${filters.sort==='popular'?'on':''}`} onClick={()=>update({sort:'popular'})}>Todos os NFTs</button><button className={`catalog-tab ${filters.sort==='newest'?'on':''}`} onClick={()=>update({sort:'newest'})}>Novos lançamentos</button><button className={`catalog-tab ${filters.sort==='price_desc'?'on':''}`} onClick={()=>update({sort:'price_desc'})}>Em alta</button></div><label className="sort-control">Ordenar por:<select aria-label="Ordenar NFTs" value={filters.sort} onChange={e=>update({sort:e.target.value as CatalogFilters['sort']})}><option value="popular">Listados recentemente</option><option value="newest">Novos lançamentos</option><option value="price_asc">Menor preço</option><option value="price_desc">Maior preço</option></select></label></div>
{(mobileFilters||showSearch)&&<div className="search-inline"><input aria-label="Buscar NFT" type="search" placeholder="Buscar NFT ou criador" value={filters.q} onChange={e=>update({q:e.target.value})}/><select className="plain" aria-label="Filtrar categoria" value={filters.category} onChange={e=>category(e.target.value)}><option value="all">Todas as coleções</option>{categories.map(([name])=><option key={name}>{name}</option>)}</select><button className="icon-btn" onClick={()=>{setShowSearch(false);setMobileFilters(false)}}>×</button></div>}
<div role="status" aria-live="polite" className="small-copy muted" style={{margin:'-2px 0 12px'}}>{isFetching?'Atualizando catálogo…':data?`${data.total} NFTs encontrados`:''}</div>
{isError?<div className="panel"><Feedback message="Não foi possível carregar o catálogo."/><Button onClick={()=>void refetch()}>Tentar novamente</Button></div>:isPending?<Loading count={8}/>:data?.items.length?<div className="grid-nfts">{data.items.map(nft=><NftCard key={nft.id} nft={nft}/>)}</div>:<p className="panel">Nenhum NFT encontrado. Ajuste os filtros ou tente outro termo.</p>}
<nav className="page-numbers" aria-label="Paginação do catálogo"><button disabled={filters.page<=1} onClick={()=>update({page:filters.page-1})}>‹</button>{Array.from({length:Math.min(4,Math.max(1,Math.ceil((data?.total??0)/9)))},(_,i)=><button key={i} className={filters.page===i+1?'current':''} onClick={()=>update({page:i+1})}>{i+1}</button>)}<button disabled={!data||filters.page*9>=data.total} onClick={()=>update({page:filters.page+1})}>›</button></nav>
</div></section>{mode==='home'&&<><section className="promo-grid"><div className="promo-card"><img alt="Emerald Ape" src="/assets/emerald.webp"/><div><strong>Lançamentos gênesis<br/>de edição limitada</strong><p>Colecione edições escassas diretamente dos criadores antes da revelação pública.</p><Link to="/market" className="btn small" search={defaultCatalogSearch}>Explorar →</Link></div></div><div className="promo-card"><img alt="Ivory Baron" src="/assets/ivory.webp"/><div><strong>Arte digital selecionada<br/>e muito mais</strong><p>Explore novos artistas, coleções verificadas e obras digitais que definem a cultura.</p><Link to="/market" className="btn small" search={defaultCatalogSearch}>Explorar →</Link></div></div></section><section className="editorial"><h2>Diário da Cunhagem</h2><p>Histórias, guias e insights para colecionadores sobre o universo da propriedade digital.</p><div className="article-grid">{[['ivory','Como funciona a propriedade de NFTs'],['emerald','10 artistas digitais para acompanhar'],['sage','Raridade, atributos e procedência'],['golden','Como proteger sua carteira']].map(([image,title])=><article className="article-card" key={title}><img alt={`Arte de ${title}`} loading="lazy" src={`/assets/${image}.webp`}/><div className="article-body"><small>12 de setembro | Leitura de 6 min</small><h3>{title}</h3><p>Descubra mais sobre a cultura digital.</p></div></article>)}</div></section></>}
</>}
export function Home(){return <Catalog mode="home"/>}
export function Market(){return <Catalog mode="market"/>}

function DetailSkeleton(){return <div className="detail-placeholder" role="status" aria-label="Carregando detalhes do NFT" aria-busy="true"><div className="crumb"><span>Início / Mercado</span></div><div className="mobile-detail-head mobile-only"><div className="skeleton detail-skeleton-icon" aria-hidden="true"/><div className="skeleton detail-skeleton-icon" aria-hidden="true"/></div><section className="detail-top"><div className="detail-visual"><div className="detail-thumbs">{Array.from({length:4},(_,i)=><div key={i} className="skeleton detail-skeleton-thumb" aria-hidden="true"/>)}</div><div className="detail-hero"><div className="skeleton detail-skeleton-art" aria-hidden="true"/></div></div><div className="detail-info"><div className="skeleton detail-skeleton-heading" aria-hidden="true"/><div className="skeleton detail-skeleton-price" aria-hidden="true"/><div className="skeleton detail-skeleton-label" aria-hidden="true"/><div className="skeleton detail-skeleton-line" aria-hidden="true"/><div className="skeleton detail-skeleton-line short" aria-hidden="true"/><div className="skeleton detail-skeleton-label" aria-hidden="true"/><div className="skeleton detail-skeleton-pills" aria-hidden="true"/><div className="skeleton detail-skeleton-buttons" aria-hidden="true"/><div className="skeleton detail-skeleton-line" aria-hidden="true"/><div className="skeleton detail-skeleton-line" aria-hidden="true"/><div className="skeleton detail-skeleton-line short" aria-hidden="true"/></div></section><div className="mobile-detail-actions mobile-only"><div className="skeleton detail-skeleton-mobile-button" aria-hidden="true"/></div><div className="details-tabs"><div className="skeleton detail-skeleton-tab" aria-hidden="true"/></div><div className="details-copy"><div className="skeleton detail-skeleton-line" aria-hidden="true"/><div className="skeleton detail-skeleton-line short" aria-hidden="true"/><div className="skeleton detail-skeleton-line" aria-hidden="true"/></div><div className="detail-more"><div className="skeleton detail-skeleton-label" aria-hidden="true"/></div></div>}
const galleryViews = [
  {label:'Arte completa',className:'gallery-view-full'},
  {label:'Detalhe central',className:'gallery-view-center'},
  {label:'Detalhe superior',className:'gallery-view-upper'},
  {label:'Detalhe inferior',className:'gallery-view-lower'},
] as const;
export function Detail(){const {nftId}=useParams({from:'/nfts/$nftId'});const {data:nft,isPending,isError,refetch}=useQuery({queryKey:['nft',nftId],queryFn:()=>api.nft(nftId),retry:false});const qc=useQueryClient();const navigate=useNavigate();const [quantity,setQuantity]=useState(1);const [galleryState,setGalleryState]=useState({nftId,index:0});const galleryIndex=galleryState.nftId===nftId?galleryState.index:0;const setGalleryIndex=(index:number)=>setGalleryState({nftId,index});const [tab,setTab]=useState<'details'|'reviews'>('details');const add=useMutation({mutationFn:()=>api.add(nftId,quantity),onSuccess:()=>void qc.invalidateQueries({queryKey:['cart']})});const demo=useMutation({mutationFn:()=>api.demoChange(nftId),onSuccess:()=>{void qc.invalidateQueries({queryKey:['nft',nftId]});void qc.invalidateQueries({queryKey:['catalog']});void qc.invalidateQueries({queryKey:['quote']});}});if(isPending)return <DetailSkeleton/>;if(isError||!nft)return <section style={{padding:50}}><Feedback message="NFT inexistente ou indisponível."/><Link to="/market" className="btn" search={defaultCatalogSearch}>Voltar ao mercado</Link></section>;const chooseQty=(n:number)=>setQuantity(Math.max(1,Math.min(n,nft.stock)));const buy=()=>add.mutate(undefined,{onSuccess:()=>void navigate({to:'/cart'})});return <><div className="crumb"><Link to="/" search={defaultCatalogSearch}>Início</Link> / <Link to="/market" search={defaultCatalogSearch}>Mercado</Link></div><div className="mobile-detail-head mobile-only"><Link to="/market" aria-label="Voltar ao mercado" className="icon-btn" search={defaultCatalogSearch}><ArrowLeft size={20}/></Link><Favorite id={nftId} className="mobile-detail-fav"/></div><section className="detail-top"><div className="detail-visual"><div className="detail-thumbs" role="group" aria-label="Visualizações da arte">{galleryViews.map((view,i)=><button key={view.label} type="button" aria-label={view.label} aria-pressed={galleryIndex===i} className={galleryIndex===i?'active':''} onClick={()=>setGalleryIndex(i)}><img className={view.className} src={nft.image} alt=""/></button>)}</div><div className="detail-hero"><div className="gallery-viewport"><img className={galleryViews[galleryIndex].className} src={nft.image} alt={`Arte digital ${nft.title} — ${galleryViews[galleryIndex].label}`} fetchPriority="high"/></div><div className="gallery-mobile-controls mobile-only" role="group" aria-label="Visualizações da arte">{galleryViews.map((view,i)=><button key={view.label} type="button" className={galleryIndex===i?'active':''} aria-label={view.label} aria-pressed={galleryIndex===i} onClick={()=>setGalleryIndex(i)}/>)}</div></div></div><div className="detail-info"><div className="row" style={{justifyContent:'space-between',alignItems:'start'}}><h1>{nft.title}</h1><span className="rating">★ 4.8 (19)</span></div><div className="detail-price">{formatEth(nft.priceEth)}</div><p className="detail-subtitle">Sobre este NFT:</p><p className="desc">{nft.description}</p><p className="small-copy" style={{marginTop:10,fontWeight:700}}>Edição:</p><div className="edition-pills"><span className="edition-pill">1/1</span><span className="edition-pill">1/10</span><span className="edition-pill chosen">1/50</span><span className="edition-pill">ABERTA</span></div><div className="detail-actions"><div className="qty" aria-label="Quantidade"><button aria-label="Diminuir quantidade" disabled={quantity<=1} onClick={()=>chooseQty(quantity-1)}>−</button><span aria-live="polite">{quantity}</span><button aria-label="Aumentar quantidade" disabled={quantity>=nft.stock} onClick={()=>chooseQty(quantity+1)}>+</button></div><Button className="desktop-buy" disabled={add.isPending||nft.stock===0} onClick={buy}>COMPRAR</Button><Button variant="secondary" disabled={add.isPending||nft.stock===0} onClick={()=>add.mutate()}><ShoppingCart size={15}/> Adicionar</Button><Favorite id={nftId} className=""/></div><div className="details-meta"><p>ID do token: #{nft.id.replace('nft-','').padStart(4,'0')}</p><p>Coleção: Kurio Apes</p><p>Atributos: Óculos, Esmeralda, Raro</p><p>Rede: {nft.network}</p><p>Disponíveis: {nft.stock}</p></div>{add.isSuccess&&<p role="status" className="success">NFT adicionado ao carrinho.</p>}{add.isError&&<Feedback message={errorMessage(add.error)}/>}</div></section>
<div className="mobile-detail-actions mobile-only"><Button disabled={add.isPending||nft.stock===0} onClick={buy}>Comprar NFT · {formatEth(nft.priceEth)}</Button><button aria-label="Adicionar ao carrinho" className="round-btn" disabled={add.isPending||nft.stock===0} onClick={()=>add.mutate()}><ShoppingCart size={20}/></button></div>
<section className="details-tabs"><button onClick={()=>setTab('details')} className={tab==='details'?'active':''}>Detalhes do NFT</button><button onClick={()=>setTab('reviews')} className={tab==='reviews'?'active':''}>Avaliações de colecionadores (19)</button></section><div className="details-copy">{tab==='details'?<><p>{nft.description} Cada atributo fica armazenado nos metadados do token e verificado na Ethereum. A obra explora identidade, movimento e luz em um mundo digital sem fronteiras.</p><p style={{marginTop:15}}>A propriedade inclui a arte em alta resolução, lançamentos exclusivos para colecionadores e um registro permanente de procedência registrada na rede.</p><p style={{marginTop:15}}><b style={{color:'white'}}>Rede:</b><br/>Cunhado na Ethereum com procedência imutável e metadados armazenados no IPFS.</p><p><b style={{color:'white'}}>Contrato:</b><br/>Direitos autorais do criador: 5% nas vendas secundárias.</p></>:<p>As avaliações demonstrativas serão disponibilizadas em uma próxima etapa.</p>}</div>
<div className="detail-more"><div className="row" style={{justifyContent:'space-between'}}><h2>Mais desta coleção</h2><button className="text-link" onClick={()=>demo.mutate()} disabled={demo.isPending}>Simular alteração de preço (teste)</button></div><Related exclude={nft.id}/></div><button onClick={()=>void refetch()} style={{display:'none'}} aria-hidden="true" tabIndex={-1}>Atualizar</button></>}
function Related({exclude}:{exclude?:string}){const {data}=useQuery({queryKey:['related'],queryFn:()=>api.catalog({q:'',category:'all',sort:'popular',page:1})});return <div className="related-grid">{data?.items.filter(n=>n.id!==exclude).slice(0,5).map(n=><NftCard key={n.id} nft={n}/>)}</div>}

function Quantity({value,onChange,disabled=false}:{value:number;onChange:(v:number)=>void;disabled?:boolean}){return <div className="qty"><button aria-label="Diminuir" disabled={disabled||value<=1} onClick={()=>onChange(value-1)}>−</button><span>{value}</span><button aria-label="Aumentar" disabled={disabled} onClick={()=>onChange(value+1)}>+</button></div>}
function QuoteLines({quote,loading}:{quote?:{subtotalEth:string;discountEth:string;networkFeeEth:string;totalEth:string};loading:boolean}){return <div aria-live="polite">{loading?<div className="skeleton" style={{height:145}}/>:quote?<><div className="summary-line"><span>Subtotal</span><span>{formatEth(quote.subtotalEth)}</span></div><div className="summary-line"><span>Desconto do lançamento</span><span>(−) {formatEth(quote.discountEth)}</span></div><div className="summary-line"><span>Taxa de rede</span><span>{formatEth(quote.networkFeeEth)}</span></div><p style={{fontSize:11,color:'var(--warm2)',textAlign:'right'}}>Taxa estimada</p><div className="summary-line summary-total"><strong>Total</strong><strong className="orange">{formatEth(quote.totalEth)}</strong></div></>:<p className="note">Cotação indisponível.</p>}</div>}
export function CartPage(){const {data:user}=useSession();const {data:cart,isPending,isError,refetch}=useCart();const nfts=useCartNfts(cart);const qc=useQueryClient();const [code,setCode]=useState('');const mutation=useMutation({mutationFn:({id,quantity}:{id:string;quantity:number})=>quantity===0?api.remove(id):api.setQuantity(id,quantity),onSuccess:()=>{void qc.invalidateQueries({queryKey:['cart']});void qc.invalidateQueries({queryKey:['quote']})}});const coupon=useMutation({mutationFn:api.coupon,onSuccess:(updatedCart)=>{qc.setQueryData(['cart',user?.id??'guest'],updatedCart);void qc.invalidateQueries({queryKey:['quote']});}});const quote=useQuery({queryKey:['quote','cart',JSON.stringify(cart)],queryFn:api.quote,enabled:!!cart?.items.length,retry:false});if(isPending)return <Loading count={2}/>;if(isError)return <><Feedback message="Falha ao carregar carrinho"/><Button onClick={()=>void refetch()}>Tentar novamente</Button></>;return <><div className="crumb"><Link to="/" search={defaultCatalogSearch}>Início</Link> / <Link to="/market" search={defaultCatalogSearch}>Mercado</Link> / Carrinho</div><h1 className="cart-heading mobile-only">Carrinho de NFTs</h1>{!cart?.items.length?<section className="panel" style={{padding:40,textAlign:'center'}}><h1 className="section-title">Seu carrinho está vazio</h1><p className="note" style={{margin:'15px 0'}}>Que tal descobrir sua próxima obra digital?</p><Link className="btn" to="/market" search={defaultCatalogSearch}>Explorar NFTs</Link></section>:<div className="cart-layout"><section><div className="table-head"><span>NFTs</span><span>Preço</span><span>Edições</span><span>Total</span><span/></div>{cart.items.map((item,i)=>{const nft=nfts[i]?.data;return <article className="cart-row" key={item.nftId}><div className="product-inline">{nft?<img src={nft.image} alt=""/>:<div className="skeleton" style={{width:60,height:60}}/>}<div><strong>{nft?.title??item.nftId}</strong><p>ID do token: #{nft?.id.replace('nft-','').padStart(4,'0')??'...'}</p></div></div><span className="cart-unit">{nft?formatEth(nft.priceEth):'...'}</span><div className="cart-qty"><Quantity value={item.quantity} disabled={mutation.isPending} onChange={quantity=>mutation.mutate({id:item.nftId,quantity})}/></div><strong className="cart-price cart-amount">{nft?formatEth(mulEth(nft.priceEth,item.quantity)):'...'}</strong><button className="icon-btn cart-remove" aria-label={`Remover ${nft?.title??item.nftId}`} disabled={mutation.isPending} onClick={()=>mutation.mutate({id:item.nftId,quantity:0})}><Trash2 size={18} color="#b99a75"/></button></article>})}{mutation.isError&&<Feedback message={errorMessage(mutation.error)}/>}</section><aside className="cart-summary"><h2>Resumo da carteira</h2><form onSubmit={e=>{e.preventDefault();coupon.mutate(code.trim().toUpperCase()||null)}}><label className="small-copy" htmlFor="coupon">Código promocional</label><div className="promo-form"><input id="coupon" placeholder="Digite o código promocional..." value={code} onChange={e=>setCode(e.target.value)}/><Button type="submit" disabled={coupon.isPending}>Aplicar</Button></div></form>{cart.coupon&&<div className="row"><span className="orange">Cupom: {cart.coupon}</span><button className="text-link" onClick={()=>coupon.mutate(null)}>Remover</button></div>}{coupon.isError&&<Feedback message={errorMessage(coupon.error)}/>}<QuoteLines quote={quote.data} loading={quote.isPending||quote.isFetching}/>{quote.isError&&<Feedback message={errorMessage(quote.error)}/>}<Link to="/checkout" className="btn wide" style={{marginTop:20,pointerEvents:quote.isError?'none':undefined}} aria-disabled={quote.isError}>Conectar e finalizar</Link><div style={{textAlign:'center',marginTop:12}}><Link className="text-link" to="/market" search={defaultCatalogSearch}>Continuar explorando</Link></div></aside></div>}{!!cart?.items.length&&<section className="cart-related related"><h2>Colecionadores também viram</h2><Related/></section>}</>}

function AuthForm({register=false}:{register?:boolean}){const qc=useQueryClient();const [name,setName]=useState(''),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[confirm,setConfirm]=useState(''),[visible,setVisible]=useState(false);const [localError,setLocalError]=useState('');const m=useMutation({mutationFn:()=>register?api.register(name,email,password):api.login(email,password),onSuccess:response=>{localStorage.setItem('nft-token',response.token);qc.clear();qc.setQueryData(['session',response.token],response.user);const intended=sessionStorage.getItem('kurio-return');sessionStorage.removeItem('kurio-return');const target=intended&&intended.startsWith('/')&&!intended.startsWith('//')?intended:'/cart';window.location.assign(target);}});const submit=(e:React.FormEvent)=>{e.preventDefault();setLocalError('');if(register&&password!==confirm){setLocalError('As senhas não coincidem.');return}m.mutate()};return <section className="auth-page"><div className="auth-backdrop"/><div className="auth-modal"><div className="brand-mobile mobile-only">KURIO</div><h1>{register?'Criar perfil de colecionador':'Entrar'}</h1><p className="hidden sm:block">{register?'Crie seu perfil de colecionador e conecte uma carteira quando quiser.':'Entre para gerenciar sua carteira, coleção e perfil de criador.'}</p><form onSubmit={submit}>{register&&<label className="field"><span className="sr-only">Nome de usuário</span><input required minLength={2} value={name} onChange={e=>setName(e.target.value)} placeholder="Nome de usuário" autoComplete="username"/></label>}<label className="field"><span className="sr-only">E-mail</span><input required type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="Digite seu e-mail" autoComplete="email"/></label><label className="field"><span className="sr-only">Senha</span><div style={{display:'flex',position:'relative'}}><input required minLength={8} type={visible?'text':'password'} autoComplete={register?'new-password':'current-password'} value={password} onChange={e=>setPassword(e.target.value)} placeholder="Senha"/><button type="button" aria-label={visible?'Ocultar senha':'Mostrar senha'} onClick={()=>setVisible(v=>!v)} className="icon-btn" style={{position:'absolute',right:4,top:3,color:'var(--warm)'}}>{visible?<Eye size={17}/>:<EyeOff size={17}/>}</button></div></label>{register&&<label className="field"><span className="sr-only">Confirmar senha</span><input type="password" required autoComplete="new-password" minLength={8} placeholder="Confirmar senha" value={confirm} onChange={e=>setConfirm(e.target.value)}/></label>}{!register&&<p className="text-link" style={{textAlign:'right',marginTop:10}}>Esqueceu a senha?</p>}<Button type="submit" className="wide" disabled={m.isPending}>{m.isPending?'Aguarde...':register?'Criar perfil':'Entrar'}</Button>{localError&&<Feedback message={localError}/>} {m.isError&&<Feedback message={errorMessage(m.error)}/>}</form><div className="auth-alternative">Ou continue com</div><button className="disabled-social" type="button" disabled aria-label="Google indisponível na simulação">🌐 Continuar com Google</button><button className="disabled-social" type="button" disabled aria-label="Facebook indisponível na simulação">f &nbsp; Continuar com Facebook</button><p className="auth-foot" style={{textAlign:'center',marginTop:24,fontSize:13,color:'var(--muted)'}}>{register?<>Já tem uma conta? <Link className="text-link" to="/login">Entre</Link></>:<>Novo na Kurio? <Link className="text-link" to="/register">Crie uma conta</Link></>}</p><p className="note" style={{textAlign:'center',marginTop:15}}>Apenas demonstração. Usuário: alex@example.test / Demo123!</p></div></section>}
export function LoginPage(){return <AuthForm/>}
export function RegisterPage(){return <AuthForm register/>}

export function CheckoutPage(){return <Required><Checkout/></Required>}
function Checkout(){const qc=useQueryClient();const navigate=useNavigate();const {data:cart}=useCart();const nftQ=useCartNfts(cart);const {data:wallets=[],isPending:isWalletsPending}=useQuery({queryKey:['wallets'],queryFn:api.wallets});const [walletId,setWalletId]=useState('');const [review,setReview]=useState(false);const [mobileCollectorOpen,setMobileCollectorOpen]=useState(false);const [profile,setProfile]=useState({displayName:'',username:'',email:'',profileName:'',address:'',referral:'',ens:'',notes:''});const [connection,setConnection]=useState<'connected'|'refused'|'disconnected'>('connected');const quote=useQuery({queryKey:['quote','checkout',JSON.stringify(cart)],queryFn:api.quote,enabled:!!cart?.items.length,staleTime:0,retry:false});const attempt=useRef<{key:string;quoteId:string;walletId:string}|null>((()=>{try{return JSON.parse(sessionStorage.getItem('kurio-pending-checkout')||'null')}catch{return null}})());const [quoteWarning,setQuoteWarning]=useState('');const reviewedSignature=useRef<string|null>(null);useEffect(()=>{if(review&&quote.data?.signature&&reviewedSignature.current!==quote.data.signature){setReview(false);setQuoteWarning('Preço ou disponibilidade alterados. Confira a nova cotação antes de confirmar.')}},[quote.data?.signature,review]);useEffect(()=>{const pending=attempt.current;if(!pending)return;void api.orderByKey(pending.key).then(async order=>{sessionStorage.removeItem('kurio-pending-checkout');attempt.current=null;await navigate({to:'/orders/$orderId',params:{orderId:order.id}})}).catch((err:unknown)=>{if((err as {response?:{status:number}}).response?.status===404){attempt.current=null;sessionStorage.removeItem('kurio-pending-checkout')}})},[navigate]);const m=useMutation({mutationFn:async()=>{if(attempt.current){try{return await api.orderByKey(attempt.current.key)}catch(error){if((error as {response?:{status:number}}).response?.status!==404)throw error;attempt.current=null;sessionStorage.removeItem('kurio-pending-checkout')}}if(!quote.data)throw new Error('Cotação ausente');if(!review||reviewedSignature.current!==quote.data.signature)throw new Error('É necessário revisar a cotação atual antes de confirmar');const current=await api.quote();if(current.signature!==quote.data.signature||current.totalEth!==quote.data.totalEth){setReview(false);setQuoteWarning('Os preços ou taxas mudaram. Confira a nova cotação antes de confirmar.');void qc.invalidateQueries({queryKey:['quote']});throw new Error('Cotação alterada');}const selected=walletId||wallets[0]?.id;if(!selected)throw new Error('Cadastre uma carteira para continuar');const nextAttempt={key:crypto.randomUUID(),quoteId:quote.data.id,walletId:selected};attempt.current=nextAttempt;sessionStorage.setItem('kurio-pending-checkout',JSON.stringify(nextAttempt));return api.placeOrder(nextAttempt.quoteId,nextAttempt.walletId,nextAttempt.key);},onSuccess:async order=>{sessionStorage.removeItem('kurio-pending-checkout');attempt.current=null;void qc.invalidateQueries({queryKey:['cart']});await navigate({to:'/orders/$orderId',params:{orderId:order.id}});}});if(!cart?.items.length)return <section className="panel" style={{margin:50}}><h1>Carrinho vazio</h1><Link to="/market" className="text-link" search={defaultCatalogSearch}>Explorar NFTs</Link></section>;const change=(k:keyof typeof profile,v:string)=>{setProfile(old=>({...old,[k]:v}));setReview(false)};return <><div className="crumb"><Link to="/" search={defaultCatalogSearch}>Início</Link> / <Link to="/market" search={defaultCatalogSearch}>Mercado</Link> / Pagamento</div><h1 className="checkout-heading mobile-only">Pagamento com carteira</h1><div className="checkout-layout"><form id="checkout-form" className={`checkout-form${mobileCollectorOpen?' mobile-open':''}`} onSubmit={e=>{e.preventDefault();reviewedSignature.current=quote.data?.signature??null;setReview(true);}}><h2>Perfil do colecionador</h2><div className="field-grid"><label className="field"><span>Nome de exibição *</span><input required value={profile.displayName} onChange={e=>change('displayName',e.target.value)}/></label><label className="field"><span>Nome de usuário *</span><input required value={profile.username} onChange={e=>change('username',e.target.value)}/></label><label className="field"><span>Rede *</span><select required value={walletId||wallets[0]?.id||''} onChange={e=>{setWalletId(e.target.value);setReview(false)}}><option value="">Selecione uma rede / carteira</option>{wallets.map(w=><option value={w.id} key={w.id}>{w.network} — {w.label}</option>)}</select></label><label className="field"><span>Nome do perfil *</span><input required value={profile.profileName} onChange={e=>change('profileName',e.target.value)}/></label><label className="field"><span>Endereço da carteira *</span><input required pattern="0x[a-fA-F0-9]{40}" value={profile.address} onChange={e=>change('address',e.target.value)} placeholder="Endereço 0x da carteira"/></label><label className="field"><span>ENS ou carteira secundária (opcional)</span><input value={profile.ens} onChange={e=>change('ens',e.target.value)} placeholder="ENS ou carteira secundária"/></label><label className="field"><span>E-mail *</span><input required type="email" value={profile.email} onChange={e=>change('email',e.target.value)}/></label><label className="field"><span>Código de indicação</span><input value={profile.referral} onChange={e=>change('referral',e.target.value)}/></label></div><label className="field" style={{marginTop:24,maxWidth:360}}><span>Observação do colecionador (opcional)</span><textarea value={profile.notes} onChange={e=>change('notes',e.target.value)}/></label><Button type="submit" className="wide" style={{marginTop:15,maxWidth:240}}>Revisar compra</Button></form><aside className="checkout-summary"><h2>Seus NFTs</h2>{cart.items.map((item,i)=>{const nft=nftQ[i].data;return <div className="summary-item" key={item.nftId}>{nft&&<img src={nft.image} alt=""/>}<div><strong>{nft?.title??'Carregando...'}</strong><p>ID do token · (x {item.quantity})</p></div><b>{nft?formatEth(mulEth(nft.priceEth,item.quantity)):'...'}</b></div>})}<QuoteLines quote={quote.data} loading={quote.isPending||quote.isFetching}/>{quoteWarning&&<Feedback message={quoteWarning}/>} {quote.isError&&<Feedback message={errorMessage(quote.error)}/>}<div className="checkout-wallets"><h2>Carteira e rede</h2>{isWalletsPending?<Loading count={1}/>:wallets.length===0?<p className="note">Nenhuma carteira cadastrada. <Link className="text-link" to="/wallets">Adicionar carteira</Link></p>:wallets.map(w=><label className={`wallet-option ${(walletId||wallets[0]?.id)===w.id?'checked':''}`} key={w.id}><input type="radio" name="wallet" value={w.id} checked={(walletId||wallets[0]?.id)===w.id} onChange={()=>{setWalletId(w.id);setReview(false)}}/><span><strong>{w.label}</strong><p>{w.address.slice(0,6)}…{w.address.slice(-4)} · Rede {w.network}</p></span></label>)}<div className="row" style={{margin:'8px 0 18px',flexWrap:'wrap'}}>{(['connected','refused','disconnected'] as const).map(status=><label key={status} className="small-copy"><input type="radio" name="simulation" checked={connection===status} onChange={()=>setConnection(status)}/> {status==='connected'?'Conectada':status==='refused'?'Recusada':'Desconectada'}</label>)}</div></div>{connection!=='connected'&&<Feedback message="Carteira desconectada ou conexão recusada (simulação)."/>}{review&&<p className="success">Revise a cotação e clique para confirmar sua compra simulada.</p>}<Button className="wide" disabled={!wallets.length||quote.isPending||quote.isError||connection!=='connected'||m.isPending} onClick={()=>{if(!review){
 const form=document.getElementById('checkout-form') as HTMLFormElement|null;
 if(!form)return;
 if(window.matchMedia('(max-width: 640px)').matches&&!mobileCollectorOpen){
  setMobileCollectorOpen(true);
  setQuoteWarning('Preencha os dados obrigatórios para revisar a compra.');
  requestAnimationFrame(()=>{
   form.scrollIntoView({block:'start',behavior:'smooth'});
   form.querySelector<HTMLInputElement>('input[required]')?.focus({preventScroll:true});
  });
  return;
 }
 if(!form.reportValidity()){
  form.scrollIntoView({block:'start',behavior:'smooth'});
  return;
 }
 setQuoteWarning('');reviewedSignature.current=quote.data?.signature??null;setReview(true);return;
}
const form=document.getElementById('checkout-form') as HTMLFormElement|null;
if(!form?.checkValidity()){
 setReview(false);
 setMobileCollectorOpen(true);
 setQuoteWarning('Revise os campos obrigatórios antes de confirmar.');
 return;
}
m.mutate()}}>{m.isPending?'Processando...':review?'Confirmar compra':'Revisar e confirmar'}</Button>{m.isError&&<><Feedback message={errorMessage(m.error)}/><Button variant="secondary" className="small" onClick={()=>{void quote.refetch();setReview(false);}}>Revalidar cotação</Button></>}<p className="note" style={{marginTop:10}}>Simulação sem conexão com blockchain ou movimentação financeira.</p></aside></div></>}
export function OrderPage(){return <Required><OrderDetail/></Required>}
function OrderDetail(){const {orderId}=useParams({from:'/orders/$orderId'});const {data:order,error,isPending}=useQuery({queryKey:['order',orderId],queryFn:()=>api.order(orderId),refetchInterval:query=>query.state.data?.status==='pending'?1000:false,retry:false});if(isPending)return <Loading count={1}/>;if(error||!order)return <Feedback message="Pedido não encontrado ou acesso negado."/>;return <section className="order-panel"><CheckCircle2 size={46} color="var(--warm)" style={{margin:'0 auto'}}/><h1>{order.status==='confirmed'?'Seus NFTs agora estão na sua carteira':order.status==='pending'?'Aguardando confirmação simulada':'Pagamento recusado'}</h1><div className="receipt-row"><span>ID da transação<br/><span className="muted">{order.id.slice(0,15)}…</span></span><span>Data<br/><span className="muted">{new Date(order.createdAt).toLocaleDateString('pt-BR')}</span></span><span>Total<br/><span className="orange">{formatEth(order.quote.totalEth)}</span></span></div><h2 style={{textAlign:'left',fontSize:15,fontWeight:700,margin:'24px 0 12px'}}>Detalhes da transação</h2>{order.quote.items.map(item=><div className="receipt-row" key={item.nftId}><span className="row">{item.image&&<img src={item.image} alt=""/>}<span>{item.title??item.nftId}<br/><small className="muted">Edição (x {item.quantity})</small></span></span><strong className="orange">{formatEth(item.lineEth)}</strong></div>)}<div className="receipt-row"><span>Taxa de rede</span><span>{formatEth(order.quote.networkFeeEth)}</span></div><div className="receipt-row"><strong>Total</strong><strong className="receipt-total">{formatEth(order.quote.totalEth)}</strong></div><p className="note" style={{margin:'16px 0 22px'}}>{order.status==='pending'?'Pedido pendente: o estado será recuperado após atualizar a página.':order.status==='declined'?'Compra recusada: os itens foram preservados no carrinho.':'Transação confirmada na simulação. Os NFTs foram registrados para a carteira de teste.'}</p>{order.status==='confirmed'?<span className="btn secondary">Ver no Etherscan (simulado)</span>:<Link to="/cart" className="btn">Voltar ao carrinho</Link>}{order.txRef&&<p className="note" style={{wordBreak:'break-all',marginTop:15}}>{order.txRef}</p>}</section>}

function AccountShell({section,children}:{section:'profile'|'wallets';children:React.ReactNode}){const qc=useQueryClient();const navigate=useNavigate();return <div className="account-grid"><aside className="account-menu"><h2>Meu perfil</h2><Link className={section==='profile'?'active':''} to="/profile"><UserRound size={17}/>Dados do perfil</Link><Link className={section==='wallets'?'active':''} to="/wallets"><WalletIcon size={17}/>Carteiras</Link><span className="disabled-menu">Atividade</span><span className="disabled-menu">Lista de interesse</span><span className="disabled-menu">Ofertas</span><span className="disabled-menu">Arquivos baixados</span><button onClick={async()=>{await clearIdentity(qc);await navigate({to:'/',search:defaultCatalogSearch})}}><LogOut size={16}/>Sair</button></aside><section className="account-content">{children}</section></div>}
export function ProfilePage(){return <Required><Profile/></Required>}
function Profile(){
 const {data:user}=useSession();const qc=useQueryClient();
 const [name,setName]=useState(user?.name??'');const [email,setEmail]=useState(user?.email??'');
 const [username,setUsername]=useState(user?.username??'');const [ens,setEns]=useState(user?.ens??'');
 const [walletAlias,setWalletAlias]=useState(user?.walletAlias??'');const [avatar,setAvatar]=useState(user?.avatar??'');
 const [current,setCurrent]=useState('');const [next,setNext]=useState('');const [confirm,setConfirm]=useState('');
 const [passError,setPassError]=useState('');
 useEffect(()=>{setName(user?.name??'');setEmail(user?.email??'');setUsername(user?.username??'');setEns(user?.ens??'');setWalletAlias(user?.walletAlias??'');setAvatar(user?.avatar??'')},[user]);
 const m=useMutation({mutationFn:()=>api.profile({name,email,username,ens,walletAlias,avatar}),onSuccess:()=>void qc.invalidateQueries({queryKey:['session']})});
 const pass=useMutation({mutationFn:()=>api.changePassword(current,next),onSuccess:()=>{setCurrent('');setNext('');setConfirm('')}});
 return <AccountShell section="profile"><h1>Perfil do colecionador</h1>
 <form onSubmit={e=>{e.preventDefault();m.mutate()}}>
  <div className="field-grid">
   <label className="field"><span>Nome de exibição *</span><input required value={name} onChange={e=>setName(e.target.value)}/></label>
   <label className="field"><span>Nome de usuário *</span><input required value={username} onChange={e=>setUsername(e.target.value)} placeholder="colecionador"/></label>
   <label className="field"><span>E-mail *</span><input type="email" required value={email} onChange={e=>setEmail(e.target.value)}/></label>
   <label className="field"><span>Nome ENS</span><input value={ens} onChange={e=>setEns(e.target.value)} placeholder=".eth"/></label>
   <label className="field"><span>Apelido da carteira</span><input value={walletAlias} onChange={e=>setWalletAlias(e.target.value)} placeholder="Principal"/></label>
   <label className="field"><span>Avatar</span><span className="row" style={{gap:12}}>{avatar?<img src={avatar} alt="Seu avatar" style={{width:45,height:45,objectFit:'cover',borderRadius:'50%'}}/>:<span className="footer-disc" style={{width:42,height:42,margin:0}}><ImageIcon size={16}/></span>}
    <input aria-label="URL do avatar" value={avatar} onChange={e=>setAvatar(e.target.value)} placeholder="URL da imagem"/></span></label>
  </div>
  <Button type="submit" style={{marginTop:25}} disabled={m.isPending}>Salvar perfil</Button>
  {m.isSuccess&&<p role="status" className="success">Perfil atualizado com sucesso.</p>}{m.isError&&<Feedback message={errorMessage(m.error)}/>}
 </form>
 <form onSubmit={e=>{e.preventDefault();setPassError('');if(next!==confirm){setPassError('Confirmação de senha diferente.');return}pass.mutate()}}>
  <h2>Alterar senha</h2><div className="field-grid">
   <label className="field"><span>Senha atual</span><input type="password" autoComplete="current-password" required value={current} onChange={e=>setCurrent(e.target.value)}/></label><span/>
   <label className="field"><span>Nova senha</span><input type="password" autoComplete="new-password" required minLength={8} value={next} onChange={e=>setNext(e.target.value)}/></label><span/>
   <label className="field"><span>Confirmar nova senha</span><input type="password" autoComplete="new-password" required minLength={8} value={confirm} onChange={e=>setConfirm(e.target.value)}/></label>
  </div><Button type="submit" style={{marginTop:25}} disabled={pass.isPending}>Alterar senha</Button>
  {passError&&<Feedback message={passError}/>} {pass.isError&&<Feedback message={errorMessage(pass.error)}/>} {pass.isSuccess&&<p className="success" role="status">Senha alterada.</p>}
 </form>
 </AccountShell>
}
export function WalletsPage(){return <Required><Wallets/></Required>}
function Wallets(){
 const qc=useQueryClient();const {data:wallets=[],isPending}=useQuery({queryKey:['wallets'],queryFn:api.wallets});
 const [editId,setEditId]=useState<string|null>(null);const [label,setLabel]=useState('');const [address,setAddress]=useState('');const [network,setNetwork]=useState<Wallet['network']>('Ethereum');const [primary,setPrimary]=useState(false);
 const reset=()=>{setEditId(null);setLabel('');setAddress('');setNetwork('Ethereum');setPrimary(false)};
 const m=useMutation({mutationFn:()=>editId?api.updateWallet(editId,{label,address,network,primary}):api.addWallet({label,address,network,primary}),onSuccess:()=>{reset();void qc.invalidateQueries({queryKey:['wallets']})}});
 return <AccountShell section="wallets"><div className="row" style={{justifyContent:'space-between'}}><h1>Carteira principal</h1><button className="text-link" type="button" onClick={reset}>Adicionar</button></div>
 <p className="note" style={{margin:'-18px 0 25px'}}>Estas carteiras ficam disponíveis no pagamento e para receber NFTs comprados.</p>
 {isPending?<Loading count={1}/>:wallets.map(w=><div key={w.id} className="panel" style={{marginBottom:12}}><div className="row" style={{justifyContent:'space-between'}}><b>{w.label} · {w.network} {w.primary?'· Principal':'· Secundária'}</b><button type="button" className="text-link" onClick={()=>{setEditId(w.id);setLabel(w.label);setAddress(w.address);setNetwork(w.network);setPrimary(w.primary)}}>Editar</button></div><p className="note" style={{wordBreak:'break-all'}}>{w.address}</p></div>)}
 <h2>{editId?'Editar carteira':'Adicionar carteira de teste'}</h2>
 <form onSubmit={e=>{e.preventDefault();m.mutate()}}><div className="field-grid">
 <label className="field"><span>Nome de exibição *</span><input required value={label} onChange={e=>setLabel(e.target.value)} placeholder="Minha carteira"/></label>
 <label className="field"><span>Apelido da carteira *</span><input required value={label} onChange={e=>setLabel(e.target.value)}/></label>
 <label className="field"><span>Rede *</span><select value={network} onChange={e=>setNetwork(e.target.value as Wallet['network'])}><option>Ethereum</option><option>Polygon</option></select></label>
 <label className="field"><span>Nome do perfil *</span><input value={label} onChange={e=>setLabel(e.target.value)} required/></label>
 <label className="field"><span>Endereço da carteira *</span><input required pattern="0x[a-fA-F0-9]{40}" value={address} onChange={e=>setAddress(e.target.value)} placeholder="Endereço 0x da carteira"/></label>
 <label className="field"><span>ENS ou carteira secundária (opcional)</span><input disabled placeholder="Campo informativo da maquete"/></label></div>
 <label className="row" style={{margin:'20px 0'}}><input type="checkbox" checked={primary} onChange={e=>setPrimary(e.target.checked)}/> Definir como carteira principal</label>
 <div className="row"><Button type="submit" disabled={m.isPending}>{editId?'Atualizar carteira':'Salvar carteira'}</Button>{editId&&<Button type="button" variant="secondary" onClick={reset}>Cancelar</Button>}</div>
 {m.isError&&<Feedback message={errorMessage(m.error)}/>} {m.isSuccess&&<p role="status" className="success">Carteira salva.</p>}
 </form><h2>Carteira secundária</h2><p className="note">{wallets.some(w=>!w.primary)?'As carteiras secundárias estão listadas acima.':'Você ainda não adicionou uma carteira secundária.'}</p></AccountShell>
}
export function NotFound(){return <section className="panel" style={{marginTop:70}}><h1 className="section-title">Página não encontrada</h1><Link className="btn" to="/" search={defaultCatalogSearch}>Voltar para início</Link></section>}
